INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구시다 신사', '櫛田神社', 'SHRINE_TEMPLE', '福岡県', '福岡市博多区', 33.592900, 130.410500, 'FIXED', '04:00', '22:00', NULL, '참배 4:00~22:00, 授与所 9:00~17:00', '무료', '757년 창건으로 전해지는 "博多의 총진수". 7월 하카타 기온 야마카사가 봉납되는 신사다.', '경내에 장식 야마카사가 6월을 빼고 늘 전시돼 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('마이즈루 공원 (후쿠오카성 터)', '舞鶴公園', 'HISTORIC', '福岡県', '福岡市中央区', 33.584700, 130.383000, 'ALWAYS', NULL, NULL, NULL, '공원 출입 자유. 모란작약원·다몬야구라는 9:00~17:00', '무료', '구로다 나가마사가 쌓은 후쿠오카성 혼마루 터를 중심으로 한 공원. 덴진에서 걸어서 15분 거리이고 벚꽃 명소로 유명하다.', '바로 옆 오호리 공원과 이어서 걷기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('후쿠오카 타워', '福岡タワー', 'VIEWPOINT', '福岡県', '福岡市早良区', 33.593300, 130.351500, 'FIXED', '09:30', '22:00', NULL, '입장 21:30까지. 6월 마지막 주 월·화요일 휴관', '1,000엔', '높이 234m로 해변 타워 중 일본에서 가장 높다. 123m 전망실에서 후쿠오카 시가지와 하카타만이 360도로 보인다.', '생일인 사람은 전망료가 무료다.', NULL, 'https://www.fukuokatower.co.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('후쿠오카시 박물관', '福岡市博物館', 'MUSEUM', '福岡県', '福岡市早良区', 33.589500, 130.353700, 'FIXED', '09:30', '17:30', 'MON', '입관 17:00까지. 월요일이 공휴일이면 다음 평일 휴관. 12/28~1/4 휴관, 여름엔 시간 변경', '상설·기획전 200엔 (특별전 별도)', '국보 금인 "漢委奴國王"을 비롯해 구석기 시대부터 현대까지 후쿠오카의 역사와 생활을 소개하는 박물관.', '후쿠오카 타워에서 걸어갈 수 있는 거리다.', NULL, 'https://museum.city.fukuoka.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('마린월드 우미노나카미치', 'マリンワールド海の中道', 'AMUSEMENT', '福岡県', '福岡市東区', 33.660900, 130.364100, 'FIXED', '09:30', '17:30', NULL, '입관 16:30까지. 1월 셋째 월요일부터 4일간 휴관', NULL, '규슈의 바다를 주제로 350종 3만 점의 바다 생물을 전시하는 수족관.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다자이후 덴만구', '太宰府天満宮', 'SHRINE_TEMPLE', '福岡県', '太宰府市', 33.521500, 130.534900, 'VARIES', NULL, NULL, NULL, '개문은 춘분부터 6:00, 추분부터 6:30. 폐문은 4~5월·9~11월 19:00, 6~8월 19:30, 12~3월 18:30. 12/31~1/3은 종일 개문', '무료', '학문의 신 스가와라노 미치자네를 모신 전국 약 1만 2천 덴만구의 총본궁.', '1월 하순~3월 초 약 6,000그루 매화가 피고, 본전 앞 신목 "도비우메"가 유명하다.', NULL, 'https://www.dazaifutenmangu.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('규슈 국립박물관', '九州国立博物館', 'MUSEUM', '福岡県', '太宰府市', 33.518600, 130.538300, 'FIXED', '09:30', '17:00', 'MON', '입관 16:30까지. 월요일이 공휴일·대체휴일이면 다음 날 휴관, 연말 휴관. 야간 개관은 공식 사이트 확인', NULL, '2005년에 문을 연 일본 네 번째 국립박물관.', '다자이후 덴만구 바로 옆이라 이어서 돌기 좋다.', NULL, 'https://www.kyuhaku.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구라바엔', 'グラバー園', 'HISTORIC', '長崎県', '長崎市', 32.734300, 129.869600, 'VARIES', NULL, NULL, NULL, '대체로 8:00 개원, 폐원은 시기마다 다름 (2026년: 6/1~7/16 18:00, 7/17~10/11 21:30, 10/12~10/31 20:00). 마지막 입장 20분 전', NULL, '스코틀랜드 상인 토머스 글로버의 저택 등 국가 중요문화재 3채와 옮겨 지은 서양식 건물이 모인 정원. 나가사키항과 이나사산이 내려다보인다.', '2026년 4월에 요금이 바뀌어서 최신 요금은 공식 사이트에서 확인하자.', NULL, 'https://glover-garden.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오우라 천주당', '大浦天主堂', 'SHRINE_TEMPLE', '長崎県', '長崎市', 32.734300, 129.870500, 'FIXED', '08:30', '18:00', NULL, '입장 17:30까지. 11/1~2월 말은 17:30 폐관(입장 17:00)', '1,000엔 (그리스도교 박물관 포함)', '에도 막부 말기에 지은 고딕 양식 성당. 현존하는 가톨릭 성당 중 가장 오래돼 국보로 지정됐고, 세계유산 구성자산이다.', '구라바엔 바로 아래라 공통권으로 함께 보기 좋다.', NULL, 'https://oura-church.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('데지마', '出島', 'HISTORIC', '長崎県', '長崎市', 32.743700, 129.873000, 'FIXED', '08:00', '21:00', NULL, '마지막 입장 20분 전', NULL, '쇄국 시대에 유럽에 유일하게 열려 있던 곳. 19세기 초의 데지마를 복원해 네덜란드 상관장 집무실 등 건물을 공개한다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가사키 원폭 자료관', '長崎原爆資料館', 'MUSEUM', '長崎県', '長崎市', 32.772300, 129.864300, 'FIXED', '08:30', '17:30', NULL, '5~8월은 18:30까지, 8/7~8/9는 20:00까지. 입관 30분 전 마감. 12/29~12/31 휴관', NULL, '1945년 8월 9일 원폭 피해의 실상과 핵무기 개발의 역사, 평화를 향한 바람을 전하는 자료관.', '2026년 4월에 요금이 바뀌어 최신 요금은 공식 사이트 확인.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가사키 평화공원', '平和公園', 'PARK_GARDEN', '長崎県', '長崎市', 32.776200, 129.863600, 'ALWAYS', NULL, NULL, NULL, '상시 개방', '무료', '원폭 낙하 중심지 근처의 공원.', '원폭 자료관과 걸어서 이어 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('메가네바시', '眼鏡橋', 'HISTORIC', '長崎県', '長崎市', 32.747500, 129.882100, 'ALWAYS', NULL, NULL, NULL, '상시', '무료', '일본 3대 명교로 꼽히는 국가 중요문화재. 현존하는 가장 오래된 아치형 돌다리 중 하나로, 강물에 비친 모습이 "안경"처럼 보인다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이나사산 전망대', '稲佐山展望台', 'VIEWPOINT', '長崎県', '長崎市', 32.754800, 129.851900, 'FIXED', '09:00', '22:00', NULL, '옥상 전망소는 24시간 개방. 로프웨이·슬로프카로 오를 수 있음', NULL, '"세계 신 3대 야경"으로 꼽힌 나가사키 야경을 보는 대표 명소.', '슬로프카는 9:00~22:00 운행한다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('나가사키 신치 차이나타운', '長崎新地中華街', 'HISTORIC', '長崎県', '長崎市', 32.741300, 129.876600, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게마다 영업시간이 다름', '무료', '요코하마·고베와 함께 일본 3대 차이나타운. 약 100m 사방의 십자로에 30여 가게가 늘어서 있다.', '가게 앞에서 산 만두나 중국 과자를 먹으며 돌면 30분쯤 걸린다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('슈리성 공원', '首里城公園', 'HISTORIC', '沖縄県', '那覇市', 26.217000, 127.719500, 'FIXED', '08:00', '19:30', NULL, '무료 구역 기준, 12~3월은 18:30까지. 유료 구역은 8:30~19:00(12~3월 18:00). 정전 내부는 사전 예약제', '유료 구역 1,000엔 (2026/11/23부터, 이전 400엔)', '약 450년간 이어진 류큐 왕국의 정치·외교·문화 중심지. 2019년 화재로 탄 정전을 복원해 2026년 11월 23일부터 다시 공개한다.', '정전 안을 보려면 사전 예약이 필요하고, 정전 외 유료 구역은 예약 없이 들어갈 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('제1 마키시 공설시장', '第一牧志公設市場', 'MARKET', '沖縄県', '那覇市', 26.214500, 127.689200, 'VARIES', NULL, NULL, NULL, '대체로 8:00~21:00 (가게마다 다름). 넷째 일요일(12월 제외)·1/1~1/3·음력 설·추석 휴무', '무료', '1950년부터 이어진 "오키나와의 부엌". 1층엔 생선·고기·섬 채소 가게, 2층엔 오키나와 음식 식당이 있다.', '1층에서 산 재료를 2층 식당에서 조리해 먹을 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시키나엔', '識名園', 'PARK_GARDEN', '沖縄県', '那覇市', 26.203900, 127.716700, 'FIXED', '09:00', '18:00', 'WED', '10~3월은 17:30까지. 입장 30분 전 마감. 수요일이 공휴일·위령의 날(6/23)이면 다음 날 휴원', '400엔', '1799년에 만든 류큐 왕가 최대의 별장 정원. 세계유산 구성자산으로, 마음 심(心) 자 모양 연못을 도는 회유식 정원이다.', '일본식 정원에 중국풍 육각당과 류큐 석회암 돌다리가 어우러진다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('국제거리', '国際通り', 'HISTORIC', '沖縄県', '那覇市', 26.215700, 127.687100, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게마다 영업시간이 다름', '무료', '"기적의 1마일"이라 불리는 나하의 번화가.', '골목 안쪽으로 마키시 공설시장이 이어진다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('후쿠슈엔', '福州園', 'PARK_GARDEN', '沖縄県', '那覇市', 26.217100, 127.676400, 'FIXED', '09:00', '21:00', 'WED', '입장 20:30까지. 수요일이 공휴일이면 다음 날 휴원. 낮(~18:00)과 밤 요금이 다름', NULL, '나하시와 중국 푸저우시의 우호도시 10주년을 기념해 만든 중국식 정원.', '폭포 위 중국식 전망대에서 정원 전체가 내려다보인다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가라쓰성', '唐津城', 'HISTORIC', '佐賀県', '唐津市', 33.457300, 129.976500, 'FIXED', '09:00', '17:00', NULL, '천수각 기준, 입장 16:40까지. 12/29~12/31 휴관. 성 둘레 마이즈루 공원은 5:00~22:00 무료', '500엔', '천수각 5층 전망대에서 겐카이나다와 마쓰라가타가 내려다보이는 성. 둘레는 마이즈루 공원으로 정비돼 있다.', '4월 중순~5월 초 수령 100년 넘은 등나무가 핀다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구 다카토리 저택', '旧高取邸', 'HISTORIC', '佐賀県', '唐津市', 33.455900, 129.972900, 'FIXED', '09:30', '17:00', 'MON', '입관 16:30까지. 월요일이 공휴일이면 다음 날 휴관. 12/29~1/3 휴관', '520엔', '"히젠의 탄광왕" 다카토리 고레요시가 1905년에 지은 저택 겸 영빈관. 능 무대가 있는 대광간과 72장의 삼나무 문 그림이 볼거리인 국가 중요문화재다.', '가라쓰성에서 걸어서 10분쯤.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('니지노마쓰바라', '虹の松原', 'PARK_GARDEN', '佐賀県', '唐津市', 33.444400, 130.010000, 'ALWAYS', NULL, NULL, NULL, '상시', '무료', '약 100만 그루의 소나무가 무지개처럼 휘어진 해안 송림. 일본 3대 송림이자 국가 특별명승이다.', '송림 안에서 파는 명물 "가라쓰 버거"도 유명하다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구 가라쓰 은행', '旧唐津銀行', 'HISTORIC', '佐賀県', '唐津市', 33.451300, 129.968000, 'FIXED', '09:00', '18:00', NULL, '12/29~12/31 휴관', '무료', '1912년에 지은 붉은 벽돌 은행 건물로, 도쿄역을 설계한 다쓰노 긴고가 감수했다. 창건 당시 모습으로 복원됐다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
